function widestPairOfIndices(nums1, nums2) {
  const firstSeen = new Map();
  firstSeen.set(0, -1);
  let balance = 0;
  let widest = 0;

  for (let j = 0; j < nums1.length; j++) {
    balance += nums1[j] - nums2[j];
    if (firstSeen.has(balance)) {
      widest = Math.max(widest, j - firstSeen.get(balance));
    } else {
      firstSeen.set(balance, j);
    }
  }
  return widest;
}

